-- Each query pins every dimension except time, so the value index is the time index.

CREATE LIGHTNING DATABASE SR_EUROSTAT DESCRIBE BY "Eurostat indicators for the supplier site countries";

CREATE SCHEMASTORE CONTAINER sr_eurostat;

-- DE: unemployment_rate (une_rt_m), unemployment rate, % of labour force, monthly, seasonally adjusted
CREATE LIGHTNING REST TABLE une_rt_m_de FROM SR_EUROSTAT REQUEST(
    endpoint "https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/une_rt_m?format=JSON&geo=DE&sex=T&age=TOTAL&unit=PC_ACT&s_adj=SA&sinceTimePeriod=2015-01&lang=EN",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();

CREATE SCHEMASTORE VIEW une_rt_m_de_series WITH CONTAINER sr_eurostat AS
SELECT
    time_label AS period,
    CAST(cell_value AS DOUBLE) AS indicator_value
FROM sr_eurostat.une_rt_m_de
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, cell_value
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, time_index_value
WHERE CAST(time_key AS INT) = time_index_value;

